/**
 * The header banner prepended to generated files.
 *
 * It is applied in the pipeline after rendering and before rustfmt, so it also
 * covers files produced by user templates — no template has to repeat it.
 *
 * Three banners exist, matching the three generation strategies:
 *
 *  - **overwrite** files are regenerated on every run, so they open with the
 *    `@generated ... Do not edit by hand.` marker that editors, code hosts and
 *    review tools use to recognise generated files. A hint can point at the
 *    extension file where project code belongs.
 *  - **merge** files are generated but expected to be edited. Their banner says
 *    that generated lines are updated and edits are merged, so the file is
 *    still marked `@generated` without pretending it is read-only.
 *  - **create-only** files (the scaffold's extension points and docs) are
 *    written once and then owned by the project, so they get an "edit me"
 *    notice instead. They are deliberately *not* marked `@generated`, because
 *    hand-editing them is the intended use.
 *
 * The comment syntax follows the file type: `//` for Rust, `#` for
 * TOML/YAML/gitignore and `--` for SQL. A file type with no known syntax is left
 * untouched rather than guessed at.
 */
import type { FileStrategy } from "../generators/contract";

/** Exact file names that need a syntax not implied by their extension. */
const BY_NAME: Record<string, string> = {
  ".gitignore": "#",
  ".env.example": "#",
};

/** Comment prefix per output extension. Add new output types here. */
const BY_EXTENSION: Record<string, string> = {
  ".rs": "//",
  ".toml": "#",
  ".yaml": "#",
  ".yml": "#",
  ".example": "#",
  ".sql": "--",
};

/** Which banner a file gets; mirrors {@link RenderJob.strategy}. */
export type BannerStrategy = FileStrategy;

const OVERWRITE_MESSAGE = [
  "@generated by @em/codegen. Do not edit by hand.",
  "Edit the spec or the templates, then rerun `em-codegen gen`.",
];

const MERGE_MESSAGE = [
  "@generated by @em/codegen. Generated lines are updated on rerun.",
];

const CREATE_ONLY_MESSAGE = [
  "Scaffolded by @em/codegen. This file is yours to edit.",
  "It is written once and never overwritten by `em-codegen gen`.",
];

/** The banner comment for an output path, or `null` when the type is unknown. */
export function bannerFor(
  outPath: string,
  strategy: BannerStrategy = "overwrite",
  hint?: string,
): string | null {
  const base = outPath.split("/").pop() ?? outPath;
  const dot = base.lastIndexOf(".");
  const prefix =
    BY_NAME[base] ?? (dot > 0 ? BY_EXTENSION[base.slice(dot)] : undefined);
  if (!prefix) return null;
  const message =
    strategy === "create-only"
      ? CREATE_ONLY_MESSAGE
      : strategy === "merge"
        ? MERGE_MESSAGE
        : [...OVERWRITE_MESSAGE, ...(hint ? [hint] : [])];
  return message.map((line) => `${prefix} ${line}`).join("\n") + "\n\n";
}

/** Prepends the banner to `content`, or returns it unchanged for unknown types. */
export function withBanner(
  outPath: string,
  content: string,
  strategy: BannerStrategy = "overwrite",
  hint?: string,
): string {
  const banner = bannerFor(outPath, strategy, hint);
  return banner ? banner + content : content;
}
